const $=s=>document.querySelector(s),money=n=>'Rp'+Math.round(n).toLocaleString('id-ID'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PHOTO='https://images.unsplash.com/photo-1613977257363-707ba9348227?auto=format&fit=crop&w=1400&q=85',ROOMPHOTO='https://images.unsplash.com/photo-1611892440504-42a792e24d32?auto=format&fit=crop&w=700&q=80';
const properties=[{name:'Villa Amanah Puncak',revenue:42500000,occupancy:76,outstanding:4250000},{name:'Villa Amanah Bandung',revenue:31400000,occupancy:68,outstanding:3100000},{name:'Villa Amanah Lembang',revenue:28800000,occupancy:71,outstanding:2450000}];
const units=[{name:'Pool Villa',price:1650000,capacity:4},{name:'Garden Villa',price:1200000,capacity:4},{name:'Family Cottage',price:1450000,capacity:6},{name:'Deluxe A',price:650000,capacity:2},{name:'Deluxe B',price:650000,capacity:2},{name:'Superior Room',price:500000,capacity:2}];
const names=['Sinta Dewi','Raka Pratama','Nadia Rahma','Fajar Nugroho','Maya Putri','Kevin Santoso','Citra Maharani','Dimas Saputra','Laras Pertiwi','Reza Wibowo'];
const initial=()=>({version:1,role:'Owner',plan:'Standard',property:0,page:'overview',guided:false,step:0,yearly:false,selected:null,unit:1,checkin:'2026-11-12',checkout:'2026-11-14',guests:2,bbq:true,full:false,offer:false,rules:{payment:true,arrival:true,return:false},weekend:15,hk:['Ready','Cleaning','Dirty','Ready','Maintenance','Dirty'],bookings:Array.from({length:30},(_,i)=>{const total=units[i%6].price*(i%3+1);return{id:'AMN-'+String(1030-i),name:names[i%10],unit:i%6,property:i%3,checkin:`2026-11-${String(i%25+1).padStart(2,'0')}`,checkout:`2026-11-${String(i%25+2+i%3).padStart(2,'0')}`,total,paid:i%4===0?0:i%4===1?total/2:total,source:['Direct','OTA','WhatsApp','Walk-in'][i%4],status:['Dikonfirmasi','Menginap','Selesai','Menunggu','Dibatalkan','Refund'][i%6],new:false,created:i,payments:i%4===0?[]:[{amount:i%4===1?total/2:total,method:'Bank transfer',date:'25 Okt 2026'}]}}),events:[],interest:'Standard'});
let state;try{state=JSON.parse(localStorage.getItem('nginepin-demo-v1'));if(state?.version!==1)state=initial()}catch{state=initial()}state||=initial();let landing=true,query='',paymentOpen=false;
function persist(){try{localStorage.setItem('nginepin-demo-v1',JSON.stringify(state))}catch{}}
function track(event,detail={}){state.events.push({event,...detail,at:new Date().toISOString()});state.events=state.events.slice(-300);persist()}
const icon=(name)=>{const paths={arrow:'M4 10h12m-5-5 5 5-5 5',home:'m3 9 7-6 7 6v8H4V9m4 8v-6h4v6',chart:'M3 17V3m0 14h15M7 13V9m4 4V5m4 8V7',calendar:'M4 5h12v12H4zM7 3v4m6-4v4M4 9h12',users:'M12 17v-2c0-2-2-3-5-3s-5 1-5 3v2m12-6c2 0 4 1 4 3v3M10 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0m4-2a3 3 0 0 1 0 6',wallet:'M3 5h14v12H3zM3 5V3h11m-1 7h5v4h-5z',bed:'M2 17V6m0 7h16v4m-1-4V9H8v4M4 8h3v3H4z',spark:'m10 2 2 6 6 2-6 2-2 6-2-6-6-2 6-2z',check:'m4 10 4 4 8-9',clock:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0M10 6v4l3 2',globe:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0M3 10h14M10 3c4 4 4 10 0 14-4-4-4-10 0-14',lock:'M5 9h10v8H5zM7 9V6a3 3 0 0 1 6 0v3',layers:'m10 2 8 4-8 4-8-4 8-4M2 10l8 4 8-4M2 14l8 4 8-4',bell:'M5 14V8a5 5 0 0 1 10 0v6l2 2H3l2-2m3 4h4',reset:'M4 7a7 7 0 1 1-1 7M3 3v5h5',settings:'M3 6h14M3 14h14M7 3v6m6 2v6',invoice:'M5 2h10v16l-3-2-2 2-2-2-3 2zM8 6h4M8 9h4',send:'m2 3 16 7-16 7 3-7-3-7m3 7h13',percent:'m5 16 10-12M7 5a2 2 0 1 1-4 0 2 2 0 0 1 4 0m10 10a2 2 0 1 1-4 0 2 2 0 0 1 4 0',clean:'m6 13 8-9 2 2-8 9m-3-3 5 4-4 2-4-3 3-3',plus:'M10 3v14M3 10h14',mail:'M2 5h16v11H2zm0 0 8 6 8-6',phone:'M5 3 3 5c0 6 6 12 12 12l2-2-4-3-2 2-5-5 2-2-3-4'};return `<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[name]||paths.chart}"/></svg>`};
const logo=()=>`<a href="#" data-action="home" class="logo" aria-label="Nginepin beranda"><span class="logo-box"><img src="assets/logo.jpg" alt=""></span>nginepin<span style="color:#d1aa62">.</span></a>`;
const btn=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const photo=(src,alt,cls='')=>`<img class="${cls}" src="${src}" alt="${alt}" onerror="this.style.opacity='.15';this.removeAttribute('src')">`;
const pill=(text,cls='')=>`<span class="pill ${cls}">${text}</span>`;
const paymentStatus=b=>b.paid>=b.total?'LUNAS':b.paid>0?'DP tercatat':'Belum dibayar';
const picked=()=>state.bookings.find(b=>b.id===state.selected)||state.bookings.find(b=>b.new)||state.bookings[0];
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function modal(content){$('#modal').innerHTML=`<button class="dialog-close" data-action="close" aria-label="Tutup">×</button>${content}`;$('#modal').showModal()}
function navigate(page,role){landing=false;state.page=page;if(role)state.role=role;query='';persist();render();window.scrollTo({top:0,behavior:'instant'})}
function start(guided){state.guided=guided;state.step=0;track('demo_started');track(guided?'guided_demo_selected':'explore_selected');navigate(guided?'guest':'overview',guided?'Guest':'Owner')}
function plans(){const yearly=state.yearly;return `<div class="plans">${[['Standard','OPERATE','Bikin operasional rapi.',249000,['1 brand · 1 properti','Website direct booking','Booking, kalender & housekeeping','Pembayaran & invoice otomatis','Dashboard owner & admin']],['Pro','GROW','Bikin bisnis bertumbuh.',449000,['Semua fitur Standard','CRM & segmentasi tamu','Automation & pricing rules','Advanced upsell & laporan','Custom domain']],['Enterprise','SCALE','Satu brand. Satu pusat kendali.',999000,['Semua fitur Pro · 3 properti','Dashboard portofolio','CRM tamu lintas properti','Keuangan terkonsolidasi','Team roles & white-label / custom']]].map(([name,tag,desc,price,features],i)=>`<article class="plan ${i===1?'featured':''}">${i?`<span class="plan-badge">${i===1?'PALING POPULER':'UNTUK MULTI-PROPERTI'}</span>`:''}<div class="tagline">${tag}</div><h3>${name}</h3><p>${desc}</p><div class="plan-price">${i===2?'<span class="from">mulai</span>':''}${money(yearly?price*10:price)}<small> /${yearly?'tahun':'bulan'}</small></div><div class="billed">${yearly?'Bayar 10 bulan, gunakan 12 bulan.':'Ditagih bulanan. Fleksibel untuk bisnis Anda.'}</div><ul>${features.map(f=>`<li>${f}</li>`).join('')}</ul>${btn('Pilih '+name+' '+icon('arrow'),'choose-plan',i===1?'gold':'outline',`data-plan="${name}"`)}<p class="upgrade-note">${i===0?'Fondasi lengkap untuk operasional harian.':i===1?`Selisih ${money(yearly?2000000:200000)}/${yearly?'tahun':'bulan'} dari Standard.`:`Hemat ${money(yearly?3480000:348000)}/${yearly?'tahun':'bulan'} dibanding 3 akun Pro.`}</p></article>`).join('')}</div><p class="enterprise-note center">Enterprise termasuk 3 properti. Tambahan properti Rp125.000/bulan atau Rp1.250.000/tahun. White-label mengikuti cakupan yang disepakati.</p>`}
function billing(){return `<div class="toggle"><button data-action="monthly" class="${!state.yearly?'active':''}">Bulanan</button><button data-action="yearly" class="${state.yearly?'active':''}">Tahunan <small>Hemat 2 bulan</small></button></div>`}
function landingPage(){return `<div class="wrap"><header class="nav">${logo()}<nav class="navlinks"><a href="#cara-kerja">Cara kerja</a><a href="#paket">Paket & harga</a><a href="#" data-action="explore">Jelajahi demo</a>${btn('Konsultasi gratis '+icon('arrow'),'contact','outline')}</nav></header><main><section class="hero"><div><div class="eyebrow"><span class="dot"></span> SISTEM OPERASIONAL PENGINAPAN</div><h1>Bisnis tertata.<br>Pikiran <em>lebih lega.</em></h1><p class="intro">Dari tamu pertama kali booking hingga Anda melihat hasil bisnis. Semuanya terhubung, dalam satu tempat.</p><div class="hero-actions">${btn('Rasakan sendiri '+icon('arrow'),'guided')}${btn('Jelajahi demo','explore','outline')}</div><div class="hero-note"><span>Tanpa daftar</span><span>± 7 menit</span><span>Data simulasi</span></div></div><div class="hero-visual">${photo(PHOTO,'Villa tropis dengan kolam renang dan taman yang tenang','hero-photo')}<div class="photo-label">RUANG UNTUK BISNIS YANG BERTUMBUH</div><div class="float-card booking-float"><div class="float-head"><span class="iconbox">${icon('check')}</span><div>Booking baru masuk<small>Andi Pratama · Garden Villa</small></div><div style="margin-left:auto;color:#a1ad9f;font-size:8px">Baru saja</div></div><div class="float-line"><span>2 malam · Direct booking</span>${pill('DP tercatat')}</div></div><div class="float-card growth-float"><p>Pendapatan bulan ini</p><strong>Rp42,5 jt</strong><small>Seluruh bisnis dalam genggaman</small><div class="mini-bars">${[32,55,42,70,55,83,67,100].map(n=>`<i style="height:${n}%"></i>`).join('')}</div></div><div class="photo-caption"><strong>Lebih sedikit repot.<br>Lebih banyak kesempatan.</strong>Ilustrasi properti · Villa Amanah</div></div></section><div class="value-strip"><span>Dibuat untuk pengelola<br>penginapan yang ingin lebih.</span><div class="value">${icon('globe')} Direct booking tanpa komisi Nginepin</div><div class="value">${icon('layers')} Operasional saling terhubung</div><div class="value">${icon('chart')} Bisnis lebih mudah dipahami</div></div><section class="section" id="cara-kerja"><div class="section-heading"><div><div class="eyebrow">SATU BOOKING. SEMUA TERHUBUNG.</div><h2>Tamu nyaman. Tim tenang.<br>Anda pegang kendali.</h2></div><p>Jangan hanya melihat dashboard.<br>Coba jadi tamu, admin, dan owner di bisnis yang sama.</p></div><div class="journey-grid">${[['01','globe','Mudah untuk tamu.','Pilih kamar, tambahkan BBQ, bayar DP. Rasakan booking yang tidak berbelit.','Coba booking','guest'],['02','calendar','Rapi untuk tim.','Booking langsung masuk. Sisa pembayaran, invoice, dan status kamar ikut tersambung.','Lihat operasional','admin'],['03','chart','Jelas untuk Anda.','Lihat pendapatan, okupansi, dan peluang bisnis tanpa tenggelam di urusan harian.','Lihat dashboard owner','owner']].map(([n,ic,title,desc,cta,action])=>`<article class="journey-card"><div style="display:flex;justify-content:space-between"><span class="number">${n} / THE EXPERIENCE</span>${icon(ic)}</div><h3>${title}</h3><p>${desc}</p><button class="textbtn card-bottom" data-action="${action}" style="padding:0;width:100%">${cta}${icon('arrow')}</button></article>`).join('')}</div></section></main></div><section class="section dark"><div class="wrap demo-invite"><div><div class="eyebrow"><span class="dot"></span> BUKAN SEKADAR WEBSITE BOOKING</div><h2>Website membawa tamu.<br>Sistem merapikan bisnis.</h2><p>Ikuti satu booking dari awal sampai akhir. Dalam beberapa menit, bayangkan betapa ringannya operasional Anda besok.</p>${btn('Mulai perjalanan demo '+icon('arrow'),'guided','gold')}</div><div class="timeline">${[['1','Booking sebagai tamu','± 2 menit'],['2','Kelola sebagai admin','± 2 menit'],['3','Lihat sebagai owner','± 1 menit'],['4','Temukan ruang bertumbuh','± 2 menit']].map(([n,t,d])=>`<div class="timeline-item"><span>${n}</span>${t}<small>${d}</small></div>`).join('')}</div></div></section><div class="wrap"><section class="section" id="paket"><div class="pricing-top center"><div class="eyebrow">MULAI RAPI. TUMBUH SAAT SIAP.</div><h2>Paket yang mengikuti langkah bisnis.</h2><p>Standard sudah lengkap untuk beroperasi. Upgrade saat kebutuhan Anda bertumbuh.</p>${billing()}</div>${plans()}<button class="textbtn compare-link" data-action="pricing">Bandingkan seluruh fitur ${icon('arrow')}</button><div class="calc-strip"><div><h3>Berapa potensi penghematan direct booking Anda?</h3><p>Coba hitung biaya komisi OTA yang bisa dialihkan untuk bisnis.</p></div>${btn('Hitung potensi hemat '+icon('arrow'),'calculator','outline')}</div></section></div><section class="landing-bottom center"><div class="wrap"><h2>Operasional lebih ringan,<br>mulai dari satu percakapan.</h2><p>Ceritakan bisnis penginapan Anda. Kami bantu temukan paket yang sesuai dengan kebutuhan hari ini.</p>${btn('Bicarakan bisnis saya '+icon('arrow'),'contact')}<p class="subnote">Konsultasi via WhatsApp · Tanpa kewajiban berlangganan</p></div></section><footer class="wrap footer">${logo()}<p>© 2026 nginepin. Demo interaktif · Semua data bisnis adalah simulasi.</p><div class="footer-links"><a href="#" data-action="privacy">Privasi demo</a><a href="#" data-action="contact">Hubungi kami</a></div></footer>`}
const menus={Owner:[['overview','chart','Ringkasan'],['finance','wallet','Keuangan'],['guests','users','Data tamu'],['crm','spark','Guest CRM','Pro'],['automation','send','Automation','Pro'],['rules','percent','Pricing rules','Pro'],['portfolio','layers','Portofolio','Enterprise'],['central','globe','Central guest','Enterprise'],['team','users','Tim & akses','Enterprise']],Admin:[['today','home','Hari ini'],['bookings','calendar','Reservasi'],['calendar','calendar','Kalender'],['housekeeping','clean','Housekeeping'],['finance','wallet','Keuangan'],['guests','users','Data tamu']],Guest:[]};
function available(page){return !(['crm','automation','rules'].includes(page)&&state.plan==='Standard'||['portfolio','central','team'].includes(page)&&state.plan!=='Enterprise')}
function appShell(content){return `<header class="appbar">${logo()}<div class="appbar-right"><span class="demo-label">LIVE DEMO</span><button class="textbtn" data-action="pricing">Paket & harga</button>${btn('Konsultasi '+icon('arrow'),'contact','small')}</div></header><div class="global-controls"><div class="control"><span>Sudut pandang</span><div class="role-tabs">${['Guest','Admin','Owner'].map(r=>`<button data-action="role" data-role="${r}" class="${state.role===r?'active':''}">${r}</button>`).join('')}</div></div><div class="control"><span>Paket</span><select aria-label="Pilih paket demo" id="plan-select">${['Standard','Pro','Enterprise'].map(p=>`<option ${p===state.plan?'selected':''}>${p}</option>`).join('')}</select></div><div class="control"><select aria-label="Pilih properti" id="property-select"><option value="-1" ${state.property===-1?'selected':''}>Semua properti · Enterprise</option>${properties.map((p,i)=>`<option value="${i}" ${state.property===i?'selected':''}>${p.name}</option>`).join('')}</select></div><button class="textbtn" data-action="reset">${icon('reset')} Reset demo</button></div>${state.role==='Guest'&&['guest','checkout','confirmation','unit'].includes(state.page)?`<main class="guest-main reveal">${guide()}${content}</main>`:`<div class="app-layout"><aside class="sidebar"><div class="sidebar-label">${state.role==='Owner'?'BUSINESS OVERVIEW':'OPERASIONAL'}</div>${(menus[state.role]||menus.Owner).map(([page,ic,title,tier])=>`<button class="navitem ${state.page===page?'active':''}" data-action="nav" data-page="${page}">${icon(ic)}${title}${tier?`<small>${tier==='Enterprise'?'ENT':tier}</small>`:''}</button>`).join('')}<div style="height:18px"></div><button class="navitem ${state.page==='pricing'?'active':''}" data-action="pricing">${icon('layers')}Paket & harga</button><button class="navitem" data-action="calculator">${icon('percent')}Kalkulator hemat</button><button class="navitem" data-action="guided">${icon('spark')}Ikuti demo terpandu</button><div class="sidebar-foot">BRAND DEMO<strong>Villa Amanah</strong>Data simulasi · tersimpan di perangkat</div></aside><main class="main reveal">${guide()}${content}</main></div>`}<nav class="mobile-nav">${(state.role==='Admin'?menus.Admin.slice(0,4):state.role==='Guest'?[['guest','home','Booking'],['overview','chart','Owner'],['pricing','layers','Paket']]:[['overview','chart','Ringkasan'],['finance','wallet','Keuangan'],['crm','spark','CRM'],['portfolio','layers','Portofolio']]).concat([['pricing','layers','Paket']]).filter((x,i,a)=>a.findIndex(y=>x[0]===y[0])===i).map(([p,ic,l])=>`<button data-action="nav" data-page="${p}" class="${state.page===p?'active':''}">${icon(ic)}${l}</button>`).join('')}</nav>`}
const steps=[['Jadi tamu. Ciptakan booking pertama.','Pilih Garden Villa, tambahkan BBQ, lalu bayar DP.','Mulai dari booking'],['Booking yang sama, langsung di meja admin.','Buka reservasi Andi dan catat sisa pembayarannya.','Kelola booking'],['Pembayaran beres. Invoice ikut lunas.','Sisa pembayaran dihitung otomatis. Sekarang cek kalender dan kamar.','Lihat kalender'],['Kamar siap. Tim tahu harus apa.','Ubah Garden Villa dari Cleaning menjadi Ready.','Lihat housekeeping'],['Sekarang lihat hasilnya sebagai owner.','Booking tadi ikut tercermin dalam pendapatan dan outstanding.','Lihat sebagai Owner'],['Standard sudah merapikan operasional.','Booking, pembayaran, invoice, kalender, dan owner terhubung.','Lihat value Pro'],['Data tamu bisa menjadi kesempatan berikutnya.','Coba kirim penawaran kembali ke Raka, repeat guest Anda.','Lihat Enterprise'],['Satu brand. Banyak properti. Satu kendali.','Bandingkan tiga properti dan penghematan dibanding tiga akun Pro.','Bandingkan paket'],['Anda sudah merasakan alurnya.','Pilih paket yang sesuai dengan kebutuhan bisnis Anda.','Diskusikan kebutuhan']];
function guide(){if(!state.guided)return '';const [title,desc,cta]=steps[state.step];return `<div class="guide-progress">${steps.map((_,i)=>`<span class="${i<=state.step?'done':''}"></span>`).join('')}</div><div class="guide-banner"><div class="step">0${state.step+1}</div><div><h3>${title}</h3><p>${desc}</p></div>${state.step===0?'':btn((state.step===4&&state.page==='overview'?'Lihat nilai Standard':cta)+' '+icon('arrow'),'next','small')}<button class="textbtn" data-action="unguided" style="font-size:10px;padding:3px">Jelajah bebas</button></div>`}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${actions||'<div class="date-chip hide-small">'+icon('calendar')+' November 2026 · Demo</div>'}</div>`}
function stat(label,value,note,ic='chart'){return `<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><strong>${value}</strong><small>${note}</small></div>`}
function totals(){const ps=state.property<0?properties:[properties[state.property]];const added=state.bookings.filter(b=>b.new&&(state.property<0||b.property===state.property)&&!['Dibatalkan','Refund'].includes(b.status));return{revenue:ps.reduce((s,p)=>s+p.revenue,0)+added.reduce((s,b)=>s+b.total,0),outstanding:ps.reduce((s,p)=>s+p.outstanding,0)+added.reduce((s,b)=>s+Math.max(0,b.total-b.paid),0),occupancy:state.property<0?72:ps[0].occupancy,added}}
function chart(){return `<div class="panel"><div class="panel-title"><h3>Pendapatan bulan ini</h3><small>1–30 November 2026</small></div><div class="chart"><div class="chart-y"><span>5 jt</span><span>3 jt</span><span>1 jt</span><span>0</span></div><div class="chart-bars">${[26,35,25,49,38,66,50,35,47,31,57,39,71,54,42,68,52,80,60,87,72,64,82,100].map((v,i)=>`<i style="height:${v*.93}%" data-day="${i%5===0?i+1:''}" title="Ilustrasi tren harian"></i>`).join('')}</div></div><div class="chart-foot"><span>Tren harian ilustratif</span><strong>${money(totals().revenue)} total pendapatan</strong></div></div>`}
function sources(){return `<div class="panel"><div class="panel-title"><h3>Dari mana tamu Anda?</h3><small>Sumber booking</small></div><div class="donut-layout"><div class="donut"><div><strong>38%</strong><small>Direct booking</small></div></div><div class="legend">${[['Direct',38,'#145b46'],['OTA',34,'#92b5a0'],['WhatsApp',16,'#d1dec5'],['Walk-in',12,'#eeeede']].map(([l,v,c])=>`<div><i style="background:${c}"></i>${l}<strong>${v}%</strong></div>`).join('')}</div></div><p style="font-size:9px;margin-top:18px">Komposisi ilustratif dari baseline bisnis demo.</p></div>`}
function dashboard(){const t=totals();trackView('owner_dashboard_viewed');return heading('Selamat datang, pemilik bisnis.','Lebih sedikit menebak. Lebih banyak keputusan yang tepat.')+`<div class="stats">${stat('Pendapatan bulan ini',money(t.revenue),t.added.length?`Termasuk ${t.added.length} booking baru Anda`:'Baseline Villa Amanah · Demo','wallet')}${stat('Okupansi',t.occupancy+'%','Snapshot okupansi properti','bed')}${stat('Direct booking','38%','Tanpa komisi Nginepin','globe')}${stat('Outstanding',money(t.outstanding),'Sisa pembayaran otomatis','clock')}</div><div class="dashboard-grid">${chart()}${sources()}</div><div class="panel"><div class="panel-title"><h3>${state.property<0?'Performa seluruh properti':'Reservasi terbaru'}</h3><button class="textbtn" data-action="${state.property<0?'portfolio':'bookings'}">Lihat semua ${icon('arrow')}</button></div>${state.property<0?propertyTable():bookingTable(filteredBookings().slice(0,5))}</div><div class="insight"><span class="iconbox">${icon('spark')}</span><div><h3>${state.plan==='Standard'?'Operasional sudah rapi. Siap bantu tamu kembali?':'Satu repeat booking bisa membuka peluang baru.'}</h3><p>${state.plan==='Standard'?'Kenali repeat guest dan peluang upsell dengan Pro. Selisih Rp200.000/bulan.':'Coba CRM Raka Pratama dan simulasikan penawaran menginap kembali.'}</p></div>${btn('Lihat Guest CRM '+icon('arrow'),'crm','outline small')}</div>${state.guided&&state.step===4?`<div class="insight"><div><h3>Booking sampai laporan sudah nyambung.</h3><p>Standard mencakup direct booking, pembayaran, invoice, kalender, housekeeping, dan dashboard owner.</p></div>${btn('Standard sudah lengkap '+icon('check'),'standard-summary','small')}</div>`:''}`}
function trackView(e){if(window.lastView!==state.page){track(e);window.lastView=state.page}}
function filteredBookings(){return state.bookings.filter(b=>(state.property<0||b.property===state.property)&&(!query||(b.name+' '+b.id+' '+units[b.unit].name).toLowerCase().includes(query.toLowerCase())))}
function bookingTable(bookings){return `<div class="table-wrap"><table><thead><tr><th>TAMU / KODE BOOKING</th><th>UNIT</th><th>CHECK-IN</th><th>SUMBER</th><th>PEMBAYARAN</th><th>TOTAL</th><th></th></tr></thead><tbody>${bookings.map(b=>`<tr><td><div class="person"><span class="avatar">${esc(b.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><span>${esc(b.name)}${b.new?' '+pill('Baru'):''}<small>${esc(b.id)}</small></span></div></td><td>${units[b.unit].name}</td><td>${esc(b.checkin)}</td><td>${esc(b.source)}</td><td>${pill(paymentStatus(b),b.paid>=b.total?'':b.paid?'amber':'red')}</td><td>${money(b.total)}</td><td><button class="textbtn" data-action="booking-detail" data-id="${esc(b.id)}">Detail ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Tidak ada reservasi yang cocok.</td></tr>'}</tbody></table></div>`}
function today(){const list=filteredBookings(),newB=list.find(b=>b.new);return heading('Hari ini, lebih terkendali.','Booking masuk. Tim bergerak. Tamu disambut dengan baik.',btn('Tambah reservasi '+icon('plus'),'new-booking','small'))+`<div class="stats">${stat('Tamu akan datang',list.filter(b=>['Dikonfirmasi','Menunggu'].includes(b.status)).length,'Reservasi yang perlu disambut','users')}${stat('Tamu menginap',list.filter(b=>b.status==='Menginap').length,'Check-out sesuai jadwal','bed')}${stat('Belum lunas',list.filter(b=>b.paid<b.total&&!['Dibatalkan','Refund'].includes(b.status)).length,'Sisa dihitung oleh sistem','wallet')}${stat('Kamar perlu dibersihkan',state.hk.filter(s=>['Dirty','Cleaning'].includes(s)).length,'Cek halaman housekeeping','clean')}</div>${newB?`<div class="insight" style="margin:0 0 22px"><span class="iconbox">${icon('bell')}</span><div><h3>Booking ${esc(newB.name)} baru saja masuk.</h3><p>${units[newB.unit].name} · DP ${money(newB.paid)} · Outstanding ${money(newB.total-newB.paid)}</p></div>${btn('Kelola booking '+icon('arrow'),'booking-detail','small',`data-id="${newB.id}"`)}</div>`:''}<div class="panel"><div class="panel-title"><h3>Reservasi yang perlu perhatian Anda</h3>${btn('Semua reservasi','bookings','outline small')}</div>${bookingTable(list.slice(0,7))}</div><div class="insight"><div><h3>Tidak perlu menyalin booking dari chat ke spreadsheet.</h3><p>Data yang dibuat tamu langsung muncul di daftar reservasi yang sama.</p></div>${btn('Lihat housekeeping '+icon('arrow'),'housekeeping','outline small')}</div>`}
function bookings(){return heading('Reservasi','Satu daftar untuk booking dari semua saluran.',btn('Tambah reservasi '+icon('plus'),'new-booking','small'))+`<div class="panel"><div class="panel-title"><h3>${filteredBookings().length} reservasi</h3><input class="search-input" id="booking-search" placeholder="Cari tamu, kode, atau unit…" aria-label="Cari reservasi" value="${esc(query)}"></div><div id="booking-table">${bookingTable(filteredBookings())}</div></div>`}
function guest(){trackView('guest_booking_started');return `<div class="guest-brand"><strong>Villa Amanah<span style="color:#b09257">.</span></strong><span>${icon('globe')} ${state.plan==='Standard'?'villaamanah.nginepin.id':'villaamanah.id'} · Demo</span></div><div class="guest-hero">${photo(PHOTO,'Villa Amanah, penginapan dengan suasana tropis')}<div class="guest-hero-text"><div class="eyebrow" style="color:#cfdbbe">PUNCAK, JAWA BARAT</div><h1 style="margin-top:15px">Temukan jeda.<br>Nikmati kebersamaan.</h1><p>Villa pribadi, udara sejuk, dan waktu berkualitas bersama orang tersayang.</p></div></div><form class="searchbar" id="availability-form"><div class="field"><label for="checkin">Check-in</label><input id="checkin" type="date" value="${state.checkin}" min="2026-10-26" required></div><div class="field"><label for="checkout">Check-out</label><input id="checkout" type="date" value="${state.checkout}" min="2026-10-27" required></div><div class="field"><label for="guests">Jumlah tamu</label><select id="guests">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${state.guests===n?'selected':''}>${n} tamu</option>`).join('')}</select></div><button class="btn" type="submit">Cek ketersediaan ${icon('arrow')}</button></form><div class="panel-title"><h3>Pilih tempat beristirahat Anda</h3><small id="availability-note">${state.checkin} — ${state.checkout} · ${nights()} malam</small></div><div class="rooms">${units.map((u,i)=>{let occupied=conflict(i),capacity=u.capacity<state.guests;return `<article class="room-card">${photo(i<3?PHOTO:ROOMPHOTO,u.name)}<div class="room-body"><span class="eyebrow" style="font-size:8px">${i<3?'PRIVATE STAY':'COMFORT STAY'}</span><h3 style="margin-top:8px">${u.name}</h3><p>${u.capacity} tamu · ${i<3?'Taman pribadi':'Kamar nyaman'} · Wi-Fi</p>${pill(occupied?'Sudah dipesan':capacity?'Kapasitas tidak cukup':'Tersedia',occupied||capacity?'amber':'')}<div class="room-bottom"><div><strong>${money(u.price)}</strong><small> /malam</small></div>${btn('Lihat unit '+icon('arrow'),'unit','outline small',`data-unit="${i}"`)}</div></div></article>`}).join('')}</div><p class="center subtle" style="margin-top:25px">Powered by Nginepin · Seluruh transaksi di halaman ini adalah simulasi.</p>`}
function nights(){return Math.round((new Date(state.checkout)-new Date(state.checkin))/86400000)}
function conflict(unit){return state.bookings.some(b=>b.property===0&&b.unit===unit&&!['Dibatalkan','Refund','Selesai'].includes(b.status)&&b.checkin<state.checkout&&b.checkout>state.checkin)}
function unitDetail(){const u=units[state.unit];return heading(u.name,'Villa Amanah Puncak · Private stay',btn('Kembali ke pilihan','guest','outline small'))+`<div class="checkout-grid"><div><div class="guest-hero" style="height:350px">${photo(state.unit<3?PHOTO:ROOMPHOTO,u.name)}</div><div class="panel" style="margin-top:20px"><h3>Ruang untuk menikmati waktu.</h3><p style="font-size:12px;margin-top:15px">Kapasitas ${u.capacity} tamu. Tersedia Wi-Fi, kamar mandi pribadi, perlengkapan mandi, dan ${state.unit<3?'area taman untuk bersantai':'tempat tidur yang nyaman'}.</p><div class="notice">Check-in mulai 14.00 · Check-out maksimal 12.00. Detail fasilitas merupakan ilustrasi demo.</div></div></div><div class="panel"><h3>Ringkasan pilihan Anda</h3><div class="summary-line"><span>Check-in</span><strong>${state.checkin}</strong></div><div class="summary-line"><span>Check-out</span><strong>${state.checkout}</strong></div><div class="summary-line"><span>${nights()} malam × ${money(u.price)}</span><strong>${money(nights()*u.price)}</strong></div><p class="notice">Harga final ditampilkan sebelum konfirmasi. Tidak ada pembayaran asli pada demo ini.</p>${btn('Lanjut reservasi '+icon('arrow'),'checkout','',`style="width:100%"`)}</div></div>`}
function checkout(){const u=units[state.unit],total=nights()*u.price+(state.bbq?300000:0);return heading('Sedikit lagi, liburan dimulai.','Lengkapi reservasi. Semua data di sini untuk simulasi.',btn('Kembali','guest','outline small'))+`<form id="checkout-form" class="checkout-grid"><div class="panel"><div class="panel-title"><h3>Data tamu</h3><small>Gunakan identitas fiktif untuk mencoba</small></div><div class="form-grid"><div class="field wide"><label for="guest-name">Nama tamu</label><input id="guest-name" value="Andi Pratama" maxlength="60" required></div><div class="field"><label for="guest-phone">WhatsApp (opsional)</label><input id="guest-phone" value="081234560000" type="tel" maxlength="20"></div><div class="field"><label for="guest-email">Email demo (opsional)</label><input id="guest-email" value="andi@example.com" type="email"></div></div><h3 style="font-size:15px;margin:25px 0 12px">Buat menginap lebih berkesan</h3><label class="option"><input type="checkbox" id="bbq" ${state.bbq?'checked':''}><span>Paket BBQ<small>Untuk kebersamaan di malam hari · Rp300.000</small></span></label><h3 style="font-size:15px;margin:25px 0 12px">Pilih pembayaran</h3><label class="option"><input type="radio" name="payment" value="dp" ${!state.full?'checked':''}><span>Bayar DP 50%<small>Sisanya dilunasi sebelum menginap.</small></span></label><label class="option"><input type="radio" name="payment" value="full" ${state.full?'checked':''}><span>Bayar penuh<small>Langsung beres, lebih tenang.</small></span></label><div class="notice">Data tamu hanya tersimpan di browser ini. Tidak ada email, WhatsApp, atau pembayaran sungguhan yang dikirim.</div></div><aside class="panel" style="height:fit-content"><h3>${u.name}</h3><p style="font-size:11px;margin:10px 0 20px">${state.checkin} — ${state.checkout} · ${state.guests} tamu</p><div id="checkout-summary">${checkoutSummary()}</div><button class="btn" type="submit" style="width:100%;margin-top:20px">Konfirmasi booking demo ${icon('arrow')}</button><p class="center" style="font-size:9px;margin-top:13px">Simulasi pembayaran · Tidak perlu kartu kredit</p></aside></form>`}
function checkoutSummary(){const total=nights()*units[state.unit].price+(state.bbq?300000:0);return `<div class="summary-line"><span>${nights()} malam × ${money(units[state.unit].price)}</span><strong>${money(nights()*units[state.unit].price)}</strong></div>${state.bbq?'<div class="summary-line"><span>Paket BBQ</span><strong>Rp300.000</strong></div>':''}<div class="summary-line total"><span>Total</span><strong>${money(total)}</strong></div><div class="summary-line"><span>Dibayar sekarang ${state.full?'100%':'50%'}</span><strong>${money(state.full?total:total/2)}</strong></div><div class="summary-line"><span>Sisa pembayaran</span><strong>${money(state.full?0:total/2)}</strong></div>`}
function createBooking(form){if(state.bookings.filter(b=>b.new).length>=10){toast('Maksimal 10 booking percobaan. Reset demo untuk mencoba lagi.');return}if(conflict(state.unit)){toast('Unit ini sudah dipesan pada tanggal tersebut. Pilih unit atau tanggal lain.');return}const total=nights()*units[state.unit].price+(state.bbq?300000:0),paid=state.full?total:total/2;const b={id:'AMN-'+(2000+state.bookings.filter(b=>b.new).length),name:$('#guest-name').value.trim(),phone:$('#guest-phone').value,email:$('#guest-email').value,unit:state.unit,property:0,checkin:state.checkin,checkout:state.checkout,total,paid,source:'Direct',status:'Dikonfirmasi',new:true,bbq:state.bbq,created:Date.now(),payments:[{amount:paid,method:'Transfer bank · Demo',date:'Sekarang'}]};if(!b.name)return;state.bookings.unshift(b);state.selected=b.id;state.property=0;state.step=1;track('guest_booking_completed',{booking_id:b.id});navigate('confirmation','Guest')}
function confirmation(){const b=picked();return `<div class="panel"><div class="success-box"><div class="success-icon">${icon('check')}</div><div class="eyebrow" style="justify-content:center">BOOKING CONFIRMED · DEMO</div><h2 style="margin-top:15px">Liburan sudah di depan mata.</h2><p>Reservasi ${esc(b.name)} berhasil dibuat. Booking, DP, dan sisa pembayaran sudah tersimpan dalam satu sistem.</p>${pill(b.id)}<div style="max-width:400px;margin:20px auto;text-align:left"><div class="summary-line"><span>Unit · ${units[b.unit].name}</span><strong>${money(b.total)}</strong></div><div class="summary-line"><span>DP tercatat</span><strong>${money(b.paid)}</strong></div><div class="summary-line"><span>Outstanding otomatis</span><strong>${money(b.total-b.paid)}</strong></div></div>${btn('Lihat sebagai Admin '+icon('arrow'),'to-admin')}<p style="font-size:10px">Tamu selesai booking. Sekarang lihat apa yang terjadi di belakang layar.</p></div></div>`}
function detail(){const b=picked();return heading('Detail reservasi',b.id+' · '+b.source,btn('Semua reservasi','bookings','outline small'))+`<div class="detail-grid"><div class="panel"><div class="panel-title"><div class="person"><span class="avatar">${esc(b.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><h3>${esc(b.name)}</h3></div>${pill(b.status,b.status==='Dibatalkan'?'red':'')}</div><div class="detail-pairs"><div><label>WhatsApp demo</label><strong>${esc(b.phone||'0812-0000-0000')}</strong></div><div><label>Email demo</label><strong>${esc(b.email||'tamu@example.com')}</strong></div></div><div class="detail-section"><h4>Detail menginap</h4><div class="detail-pairs"><div><label>Unit</label><strong>${units[b.unit].name}</strong></div><div><label>Properti</label><strong>${properties[b.property].name}</strong></div><div><label>Check-in</label><strong>${esc(b.checkin)}</strong></div><div><label>Check-out</label><strong>${esc(b.checkout)}</strong></div></div></div>${b.bbq?'<div class="detail-section"><h4>Add-on</h4><p style="font-size:12px">Paket BBQ · Rp300.000</p></div>':''}<div class="detail-section"><h4>Status reservasi</h4><select id="booking-status" aria-label="Status reservasi">${['Menunggu','Dikonfirmasi','Menginap','Selesai','Dibatalkan','Refund'].map(s=>`<option ${s===b.status?'selected':''}>${s}</option>`).join('')}</select><div class="notice">Status dan pembayaran adalah dua hal terpisah. Pembatalan tidak otomatis mengubah catatan pembayaran.</div></div><div class="detail-section"><h4>Riwayat pembayaran</h4>${b.payments.map(p=>`<div class="summary-line"><span>${esc(p.method)}<br><small class="subtle">${esc(p.date)}</small></span><strong>${money(p.amount)}</strong></div>`).join('')||'<p class="subtle">Belum ada pembayaran.</p>'}</div></div><div><div class="panel"><div class="panel-title"><h3>Ringkasan pembayaran</h3>${pill(paymentStatus(b),b.paid<b.total?'amber':'')}</div><div class="summary-line"><span>Total reservasi</span><strong>${money(b.total)}</strong></div><div class="summary-line"><span>Sudah dibayar</span><strong>${money(b.paid)}</strong></div><div class="summary-line total"><span>Outstanding</span><strong>${money(Math.max(0,b.total-b.paid))}</strong></div>${b.paid<b.total?btn('Catat pembayaran '+icon('plus'),'payment','',`style="width:100%;margin-top:18px"`):'<div class="notice">Pembayaran lunas. Invoice otomatis bertanda LUNAS.</div>'}<div style="display:flex;gap:10px;margin-top:12px">${btn('Lihat invoice','invoice','outline small')}${btn('Lihat kalender','calendar','outline small')}</div></div><div class="insight"><div><h3>${b.paid>=b.total?'Selesai tanpa hitung manual.':'Sisa pembayaran sudah dihitung.'}</h3><p>${b.paid>=b.total?'Outstanding nol dan invoice lunas. Semua mengikuti catatan pembayaran yang sama.':'Begitu pembayaran dicatat, invoice dan outstanding ikut berubah.'}</p></div></div></div></div>`}
function payment(){const b=picked(),out=b.total-b.paid;modal(`<div class="eyebrow">PEMBAYARAN · SIMULASI</div><h2>Catat sekali. Langsung rapi.</h2><p>Sisa pembayaran ${esc(b.name)}: <strong>${money(out)}</strong>. Invoice akan mengikuti otomatis.</p><form id="payment-form"><div class="field"><label for="pay-amount">Nominal pembayaran (Rp)</label><input id="pay-amount" type="number" min="1" max="${out}" step="1" value="${out}" required></div><div class="field" style="margin-top:15px"><label for="pay-method">Metode</label><select id="pay-method"><option>Bank transfer</option><option>Tunai</option><option>Payment gateway · Demo</option></select></div><div class="notice">Hanya mencatat pembayaran simulasi. Tidak ada dana yang dipindahkan.</div><button class="btn" type="submit" style="width:100%">Simpan pembayaran ${icon('check')}</button></form>`)}
function invoice(){const b=picked();trackView('invoice_viewed');return `<div class="panel invoice"><div class="invoice-heading"><div><div class="eyebrow">VILLA AMANAH</div><h2 style="margin-top:12px">Invoice</h2><p style="font-size:11px;margin-top:5px">INV-${b.id} · Dokumen simulasi</p></div>${pill(b.paid>=b.total?'LUNAS':'PARTIAL',b.paid>=b.total?'':'amber')}</div><div class="detail-pairs"><div><label>Ditujukan kepada</label><strong>${esc(b.name)}</strong><p style="font-size:11px">${esc(b.email||'tamu@example.com')}</p></div><div><label>Periode menginap</label><strong>${esc(b.checkin)} — ${esc(b.checkout)}</strong></div></div><div class="detail-section"><div class="summary-line"><span>${units[b.unit].name}${b.bbq?' + BBQ':''}</span><strong>${money(b.total)}</strong></div><div class="summary-line"><span>Total pembayaran tercatat</span><strong>${money(b.paid)}</strong></div><div class="summary-line total"><span>Sisa pembayaran</span><strong class="invoice-total">${money(b.total-b.paid)}</strong></div></div><div class="notice">DEMO — Bukan bukti transaksi asli. Invoice dan outstanding berasal dari catatan pembayaran reservasi yang sama.</div><div class="dialog-actions no-print">${btn('Cetak / simpan PDF','print','outline')}${btn('Kembali ke reservasi','booking-detail','',`data-id="${b.id}"`)}</div></div>`}
function calendar(){trackView('calendar_viewed');const start=new Date(state.checkin+'T00:00:00'),days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d.toISOString().slice(0,10)});return heading('Kalender reservasi','Satu booking langsung mengisi ketersediaan unit.',btn('Housekeeping '+icon('arrow'),'housekeeping','small'))+`<div class="panel"><div class="panel-title"><h3>Villa Amanah Puncak</h3><small>${days[0]} — ${days[6]}</small></div><div class="table-wrap"><div class="calendar"><div class="cal-head">UNIT / TANGGAL</div>${days.map(d=>`<div class="cal-head">${d.slice(8)} Nov</div>`).join('')}${units.map((u,i)=>`<div><strong>${u.name}</strong></div>${days.map(d=>{const b=state.bookings.find(b=>b.property===0&&b.unit===i&&b.checkin<=d&&b.checkout>d&&!['Dibatalkan','Refund','Selesai'].includes(b.status));return `<div>${b?`<button class="cal-booking ${b.new?'new':''}" data-action="booking-detail" data-id="${b.id}">${esc(b.name)}</button>`:'<span style="color:#b4bda9">Tersedia</span>'}</div>`}).join('')}`).join('')}</div></div><div class="notice">Tanggal checkout tidak memblokir malam berikutnya. Ketersediaan dihitung dari reservasi aktif; booking yang bentrok akan dicegah.</div></div><div class="insight"><div><h3>Reservasi masuk. Kalender ikut terisi.</h3><p>Tim tidak perlu menandai booking yang sama untuk kedua kalinya.</p></div>${btn('Siapkan kamar '+icon('arrow'),'housekeeping','outline small')}</div>`}
function housekeeping(){return heading('Housekeeping','Semua orang tahu kamar mana yang siap menyambut tamu.')+`<div class="hk-grid">${units.map((u,i)=>`<article class="hk-card">${pill(state.hk[i],state.hk[i]==='Ready'?'':state.hk[i]==='Maintenance'?'red':'amber')}<h3>${u.name}</h3><p>${state.hk[i]==='Ready'?'Siap menyambut tamu berikutnya.':state.hk[i]==='Cleaning'?'Tim sedang menyiapkan kamar.':state.hk[i]==='Maintenance'?'Perlu pemeriksaan fasilitas.':'Perlu dibersihkan setelah checkout.'}</p><select aria-label="Status housekeeping ${u.name}" data-hk="${i}">${['Dirty','Cleaning','Ready','Maintenance'].map(s=>`<option ${state.hk[i]===s?'selected':''}>${s}</option>`).join('')}</select>${state.hk[i]!=='Ready'?btn('Mark Ready '+icon('check'),'ready','soft small',`data-unit="${i}" style="margin-top:12px"`):''}</article>`).join('')}</div><div class="insight"><span class="iconbox">${icon('check')}</span><div><h3>Admin mengurus operasional. Owner melihat hasilnya.</h3><p>Status kamar yang jelas membuat serah terima tim lebih mudah.</p></div>${btn('Lihat sebagai Owner '+icon('arrow'),'to-owner','small')}</div>`}
function finance(){const t=totals();return heading(state.property<0?'Keuangan terkonsolidasi':'Keuangan','Pendapatan, pembayaran, dan sisa tagihan dalam satu pandangan.')+`<div class="stats">${stat('Pendapatan',money(t.revenue),'Nilai reservasi baseline + booking demo','wallet')}${stat('Pembayaran terkumpul',money(t.revenue-t.outstanding),'Pendapatan dikurangi outstanding','check')}${stat('Outstanding',money(t.outstanding),'Otomatis dari catatan pembayaran','clock')}${stat('Booking baru',String(t.added.length),'Dibuat dalam sesi demo ini','calendar')}</div><div class="panel"><div class="panel-title"><h3>Transaksi simulasi terbaru</h3><small>Hanya catatan pembayaran · tanpa perpindahan dana</small></div><div class="table-wrap"><table><thead><tr><th>TAMU</th><th>BOOKING</th><th>METODE</th><th>JUMLAH</th><th></th></tr></thead><tbody>${filteredBookings().flatMap(b=>b.payments.map(p=>`<tr><td>${esc(b.name)}</td><td>${b.id}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td><button class="textbtn" data-action="booking-detail" data-id="${b.id}">Detail</button></td></tr>`)).slice(0,15).join('')}</tbody></table></div></div>`}
function guests(central=false){const people=Array.from(new Set(state.bookings.filter(b=>central||state.property<0||b.property===state.property).map(b=>b.name)));return heading(central?'Central guest intelligence':'Database tamu',central?'Satu hubungan dengan tamu, lintas semua properti.':'Riwayat tamu yang rapi, dimulai dari booking pertama.')+`<div class="panel"><div class="panel-title"><h3>${people.length} tamu fiktif</h3>${btn(central?'Lihat portofolio':'Coba Guest CRM',central?'portfolio':'crm','outline small')}</div><div class="table-wrap"><table><thead><tr><th>TAMU</th><th>RIWAYAT BOOKING</th><th>NILAI BOOKING</th><th>PROPERTI</th><th></th></tr></thead><tbody>${people.map(name=>{const bs=state.bookings.filter(b=>b.name===name),ps=[...new Set(bs.map(b=>properties[b.property].name.replace('Villa Amanah ','')))];return `<tr><td><div class="person"><span class="avatar">${esc(name.slice(0,1))}</span>${esc(name)}</div></td><td>${bs.length} booking</td><td>${money(bs.reduce((s,b)=>s+b.total,0))}</td><td>${central?ps.join(', '):properties[Math.max(0,state.property)].name}</td><td><button class="textbtn" data-action="guest-history" data-name="${esc(name)}">Lihat riwayat</button></td></tr>`}).join('')}</tbody></table></div></div>${!central?`<div class="insight"><div><h3>Ubah riwayat menginap menjadi peluang repeat booking.</h3><p>CRM Pro membantu mengenali tamu berulang, segmentasi, dan lifetime spend.</p></div>${btn('Preview Pro '+icon('arrow'),'crm','outline small')}</div>`:''}`}
function crm(){state.interest=state.plan==='Enterprise'?'Enterprise':'Pro';return heading('Tamu lama. Peluang baru.','Kenali siapa yang sudah menyukai properti Anda.')+`<div class="crm-hero"><div class="crm-profile"><div style="display:flex;align-items:center;justify-content:space-between"><span class="avatar">RP</span>${pill('REPEAT GUEST')}</div><h2>Raka Pratama</h2><p>Tamu direct · Terakhir menginap 5 bulan lalu</p><div class="crm-metrics"><div><strong>3</strong><small>KALI MENGINAP</small></div><div><strong>Rp5,7 jt</strong><small>LIFETIME VALUE</small></div><div><strong>Garden</strong><small>UNIT FAVORIT</small></div></div><p style="font-size:10px;margin-top:20px">Profil CRM ilustratif, terpisah dari riwayat reservasi November.</p></div><div class="value-math"><div class="eyebrow">PRO = STANDARD + RP200.000</div><h3>Hubungan baik layak dilanjutkan.</h3><p>Undang Raka kembali dengan penawaran khusus tamu lama.</p>${btn(state.offer?'Penawaran terkirim · Demo '+icon('check'):'Kirim penawaran kembali '+icon('send'),'offer','',`style="margin-top:22px"`)}<p style="font-size:10px;margin-top:12px">Simulasi. Tidak ada pesan sungguhan yang dikirim.</p></div></div><div class="dashboard-grid"><div class="panel"><div class="panel-title"><h3>Potensi dari add-on bulan ini</h3>${pill('Ilustrasi')}</div><h2 style="color:var(--green)">Rp1.250.000</h2><p style="font-size:12px;margin:14px 0">Beberapa add-on atau satu repeat booking bisa bernilai lebih besar dari selisih upgrade Rp200.000/bulan.</p><div class="notice">Contoh ilustratif, bukan jaminan pendapatan. Nilai penjualan tidak sama dengan laba; hasil bergantung pada bisnis Anda.</div></div><div class="panel"><div class="panel-title"><h3>Lebih banyak ruang bertumbuh</h3></div><div class="rules"><button class="rule" data-action="nav" data-page="automation" style="text-align:left;background:white"><div><h4>Automation</h4><p>Payment dan pre-arrival reminder.</p></div>${icon('arrow')}</button><button class="rule" data-action="nav" data-page="rules" style="text-align:left;background:white"><div><h4>Pricing rules</h4><p>Harga akhir pekan mengikuti aturan.</p></div>${icon('arrow')}</button></div></div></div><div class="insight"><div><h3>Punya lebih dari satu properti?</h3><p>Enterprise menyatukan portofolio, keuangan, dan hubungan tamu dalam satu brand.</p></div>${btn('Lihat Enterprise '+icon('arrow'),'portfolio','outline small')}</div>`}
function automation(){return heading('Otomatis untuk hal yang berulang.','Tim tetap fokus pada tamu, pengingat mengikuti aturan.')+`<div class="panel"><div class="panel-title"><h3>Alur komunikasi</h3>${pill('Semua pengiriman disimulasikan')}</div><div class="rules">${[['payment','Pengingat sisa pembayaran','H-3 check-in · Jika outstanding lebih dari Rp0'],['arrival','Sambutan sebelum kedatangan','H-1 check-in · Info lokasi dan jam check-in'],['return','Penawaran untuk tamu lama','5 bulan setelah menginap · Segmen repeat guest']].map(([k,t,d])=>`<div class="rule"><div><h4>${t}</h4><p>${d}</p></div><button class="switch ${state.rules[k]?'on':''}" data-action="toggle-rule" data-rule="${k}" role="switch" aria-checked="${state.rules[k]}" aria-label="${t}"></button></div>`).join('')}</div><div class="notice">WhatsApp automation memiliki kuota sesuai paket. Email dan pesan di demo ini tidak dikirim ke layanan eksternal.</div></div>`}
function rules(){return heading('Harga mengikuti ritme bisnis.','Simulasikan aturan harga tanpa mengubah rate satu per satu.')+`<div class="dashboard-grid"><div class="panel"><div class="panel-title"><h3>Aturan akhir pekan</h3>${pill('Pro')}</div><div class="field"><label for="weekend">Kenaikan Jumat & Sabtu (%)</label><input type="number" id="weekend" min="0" max="100" step="1" value="${state.weekend}"></div><div class="notice">Aturan tersimpan sebagai simulasi pricing. Harga booking demo memakai rate dasar agar alur percobaan tetap konsisten.</div>${btn('Simpan aturan','save-pricing','',`style="margin-top:15px"`)}</div><div class="value-math"><div class="eyebrow">PREVIEW HARGA</div><h3>Garden Villa</h3><div class="summary-line"><span>Hari biasa</span><strong>Rp1.200.000</strong></div><div class="summary-line"><span>Akhir pekan</span><strong id="weekend-preview">${money(1200000*(1+state.weekend/100))}</strong></div><p style="margin-top:15px">Contoh penerapan aturan harga. Bukan prediksi tingkat keterisian.</p></div></div>`}
function propertyTable(){return `<div class="table-wrap"><table><thead><tr><th>PROPERTI</th><th>PENDAPATAN</th><th>OKUPANSI</th><th>OUTSTANDING</th><th></th></tr></thead><tbody>${properties.map((p,i)=>{const bs=state.bookings.filter(b=>b.new&&b.property===i&&!['Dibatalkan','Refund'].includes(b.status));return `<tr><td><div class="person"><span class="iconbox">${icon('home')}</span><strong>${p.name}</strong></div></td><td>${money(p.revenue+bs.reduce((s,b)=>s+b.total,0))}</td><td>${p.occupancy}%</td><td>${money(p.outstanding+bs.reduce((s,b)=>s+b.total-b.paid,0))}</td><td><button class="textbtn" data-action="view-property" data-property="${i}">Lihat ${icon('arrow')}</button></td></tr>`}).join('')}</tbody></table></div>`}
function portfolio(){trackView('enterprise_previewed');state.interest='Enterprise';const old=state.property;state.property=-1;const t=totals();state.property=old;return heading('Satu brand. Satu pusat kendali.','Bandingkan performa tanpa berpindah akun.')+`<div class="stats">${stat('Total pendapatan',money(t.revenue),'3 properti dalam satu portofolio','wallet')}${stat('Portfolio occupancy','72%','Snapshot portofolio · Demo','bed')}${stat('Direct booking','38%','Satu brand, hubungan lebih dekat','globe')}${stat('Outstanding',money(t.outstanding),'Seluruh properti terkonsolidasi','clock')}</div><div class="panel"><div class="panel-title"><h3>Portofolio Villa Amanah</h3>${pill('3 properti termasuk')}</div>${propertyTable()}</div><div class="crm-hero" style="margin-top:22px"><div class="value-math"><div class="eyebrow">LEBIH EFISIEN UNTUK 3 PROPERTI</div><div class="summary-line"><span>3 akun Pro × Rp449.000</span><strong>Rp1.347.000/bln</strong></div><div class="summary-line"><span>Enterprise mulai</span><strong>Rp999.000/bln</strong></div><div class="big">Hemat Rp348.000/bln</div><p>Plus central CRM, keuangan konsolidasi, portfolio analytics, dan pengaturan tim.</p><div class="notice">Perbandingan langganan bulanan untuk 3 properti. Kebutuhan tambahan dan white-label mengikuti penawaran.</div></div><div class="panel"><h3 style="font-size:20px">Bukan tiga bisnis terpisah.<br>Satu brand yang bertumbuh.</h3><p style="font-size:12px;margin:17px 0">Hubungan dengan Raka tetap terjaga, dari Puncak ke Bandung hingga Lembang.</p><div class="dialog-actions">${btn('Lihat central guest','central','outline small')}${btn('Lihat tim & akses','team','outline small')}</div>${btn('Bandingkan paket '+icon('arrow'),'pricing','',`style="margin-top:25px"`)}</div></div>`}
function team(){return heading('Tim tepat. Tanggung jawab jelas.','Preview tata kelola tim lintas properti.')+`<div class="panel"><div class="panel-title"><h3>Peran dalam organisasi</h3>${pill('Enterprise')}</div><div class="table-wrap"><table><thead><tr><th>PERAN</th><th>CAKUPAN</th><th>TANGGUNG JAWAB</th></tr></thead><tbody>${[['Owner','Seluruh brand','Insight, keuangan, dan kendali portofolio'],['Property Manager','Properti yang ditugaskan','Koordinasi operasional dan tim'],['Admin','Properti yang ditugaskan','Reservasi dan pembayaran'],['Finance','Cakupan yang diizinkan','Rekonsiliasi dan laporan'],['Housekeeping','Unit yang ditugaskan','Kesiapan dan kebersihan kamar']].map(r=>`<tr>${r.map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">Preview peran demo. Pembatasan akses produksi perlu diterapkan di server; role switcher di demo hanya untuk mencoba pengalaman.</div></div>`}
function pricing(){trackView('pricing_viewed');const recommended=state.interest;return `<div class="pricing-page"><div class="pricing-top center"><div class="eyebrow">PILIH SESUAI LANGKAH BISNIS</div><h2>Mulai rapi. Tumbuh saat siap.</h2><p>${recommended==='Standard'?'Standard sudah cukup untuk kebutuhan operasional yang Anda eksplorasi.':recommended==='Pro'?'Anda mencoba CRM dan growth. Pro patut dipertimbangkan.':'Anda mencoba multi-properti. Enterprise menyatukan semuanya.'}</p>${billing()}</div>${plans()}<div class="panel feature-table"><div class="panel-title"><h3>Yang Anda dapatkan</h3><small>Bandingkan kebutuhan bisnis, bukan sekadar harga.</small></div><div class="table-wrap"><table><thead><tr><th>FITUR</th><th>Standard</th><th>Pro</th><th>Enterprise</th></tr></thead><tbody>${[['Properti termasuk','1','1','3'],['Direct booking & availability','✓','✓','✓'],['Booking, kalender, housekeeping','✓','✓','✓'],['DP, outstanding, invoice otomatis','✓','✓','✓'],['Dashboard owner & database tamu','✓','✓','✓'],['OTA iCal dasar (jika didukung)','✓','✓','✓'],['CRM & repeat guest','—','✓','Central CRM'],['Automation & pricing rules','—','✓','✓'],['Upsell','Basic','Advanced','Advanced'],['Custom domain','—','✓','✓'],['WhatsApp automation','—','Kuota','Kuota lebih tinggi'],['Multi-property & consolidated finance','—','Biaya tambahan','✓'],['White label','—','Add-on','Termasuk / custom'],['Team roles','Basic','Advanced','Multi-property']].map(r=>`<tr>${r.map((v,i)=>`<td ${i===0?'':'style="color:var(--green)"'}>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="subtle" style="margin-top:18px;font-size:10px">Sinkronisasi OTA pada demo berupa simulasi iCal dasar, bukan full API channel manager. WhatsApp, storage, AI, dan email marketing tidak diklaim unlimited.</p></div><div class="calc-strip"><div><h3>Ingin melihat potensi direct booking?</h3><p>Hitung dengan angka bisnis Anda sendiri.</p></div>${btn('Hitung penghematan','calculator','outline')}</div></div>`}
function calculator(){return heading('Biaya komisi bisa jadi ruang bertumbuh.','Gunakan angka Anda untuk melihat potensi pengalihan booking OTA.')+`<div class="calc-grid"><form class="panel" id="calc-form"><div class="field"><label for="ota-revenue">Nilai booking OTA per bulan (Rp)</label><input id="ota-revenue" type="number" min="0" max="100000000000" value="30000000" required></div><div class="field" style="margin-top:18px"><label for="ota-fee">Komisi OTA (%)</label><input id="ota-fee" type="number" min="0" max="50" step="0.1" value="15" required></div><div class="field" style="margin-top:18px"><label for="ota-shift">Booking yang dialihkan ke direct (%)</label><input id="ota-shift" type="number" min="0" max="100" value="25" required></div><button class="btn" type="submit" style="margin-top:22px">Hitung potensi ${icon('arrow')}</button><div class="notice">Tidak ada jaminan perpindahan booking. Biaya pemasaran, payment gateway, pajak, dan biaya operasional lain belum dihitung.</div></form><div class="calc-result" id="calc-result">${calcResult(30000000,15,25)}</div></div>`}
function calcResult(revenue,fee,shift){const saved=revenue*fee/100*shift/100;return `<div class="eyebrow" style="color:#d4c18a">POTENSI PENGHEMATAN / BULAN</div><strong>${money(saved)}</strong><p>${shift}% × ${money(revenue)} × ${fee}% komisi.</p><div class="summary-line" style="margin-top:25px"><span>Langganan Standard</span><b>Rp249.000</b></div><div class="summary-line"><span>Selisih setelah langganan</span><b>${money(saved-249000)}</b></div><p style="font-size:11px;margin-top:22px">${saved>=249000?'Potensi komisi yang dihemat melampaui biaya Standard dalam skenario ini.':'Dalam skenario ini, nilai operasional juga perlu dipertimbangkan sebelum memilih paket.'}</p><small style="display:block;margin-top:20px">Perhitungan ilustratif, bukan proyeksi atau jaminan hasil.</small>${btn('Diskusikan bisnis saya '+icon('arrow'),'contact','gold',`style="margin-top:25px"`)}`}
function contact(){return `<form class="panel contact-panel" id="contact-form"><div class="eyebrow">LANGKAH BERIKUTNYA, SESUAI KEBUTUHAN.</div><h2 style="margin-top:17px">Ceritakan bisnis Anda.<br>Kita rapikan bersama.</h2><p>Percakapan singkat untuk memilih paket yang tepat. Tidak ada pembayaran dari halaman demo ini.</p><div class="form-grid"><div class="field wide"><label for="business-name">Nama bisnis (opsional)</label><input id="business-name" placeholder="Contoh: Villa Cempaka" maxlength="80"></div><div class="field"><label for="contact-plan">Paket yang diminati</label><select id="contact-plan">${['Standard','Pro','Enterprise','Bantu saya memilih'].map(p=>`<option ${p===state.interest?'selected':''}>${p}</option>`).join('')}</select></div><div class="field"><label for="property-count">Jumlah properti</label><input id="property-count" type="number" min="1" max="1000" value="${state.interest==='Enterprise'?3:1}" required></div></div><div class="notice">Tombol di bawah membuka WhatsApp <strong>0859-5283-9393</strong> dengan ringkasan pilihan Anda. Pesan baru terkirim setelah Anda menekan Kirim di WhatsApp.</div><button class="btn" type="submit">Lanjut konsultasi WhatsApp ${icon('arrow')}</button><p class="center" style="font-size:10px;margin:17px 0 0">Lebih nyaman lewat email? <a data-action="email" href="#" style="color:var(--green);text-decoration:underline">Hubungi admin</a></p><p style="font-size:9px;margin-top:14px">Email ditujukan ke admin3@desainindongmas.my.id melalui aplikasi email Anda. Tidak ada pengiriman data diam-diam.</p></form>`}
function locked(page){const tier=['portfolio','central','team'].includes(page)?'Enterprise':'Pro';modal(`<div class="eyebrow">TERSEDIA DI ${tier.toUpperCase()}</div><h2>${tier==='Pro'?'Ubah data tamu menjadi peluang.':'Satu brand. Banyak properti.'}</h2><p>${tier==='Pro'?'Kenali repeat guest, coba automation, dan atur pricing. Semua fitur Standard tetap tersedia. Tambahan Rp200.000/bulan.':'Satukan tiga properti, keuangan, dan CRM. Mulai Rp999.000/bulan, hemat Rp348.000 dibanding tiga akun Pro.'}</p><div class="notice">Preview gratis di demo. Tidak mengubah langganan atau memulai pembayaran.</div><div class="dialog-actions">${btn('Preview '+tier+' '+icon('arrow'),'unlock','',`data-plan="${tier}" data-page="${page}"`)}${btn('Bandingkan paket','pricing','outline')}</div>`)}
function switchPlan(plan,page){state.plan=plan;state.interest=plan;if(plan!=='Enterprise'&&state.property<0)state.property=0;track('plan_switched',{plan});if(plan==='Pro')track('pro_previewed');if(plan==='Enterprise')track('enterprise_previewed');persist();if(page)navigate(page,'Owner');else render();if(plan!=='Standard')toast(plan+' terbuka · '+(plan==='Pro'?'CRM, automation, pricing & growth':'Portofolio, central CRM & keuangan konsolidasi'))}
function next(){if(state.step===1){state.selected=state.bookings.find(b=>b.new)?.id||picked().id;navigate('booking','Admin');return}if(state.step===2){state.step=3;navigate('calendar','Admin');return}if(state.step===3){navigate('housekeeping','Admin');return}if(state.step===4){if(state.page!=='overview'){navigate('overview','Owner');return}state.step=5;modal(`<div class="eyebrow">STANDARD · OPERATE</div><h2>Sudah menjadi sistem operasional.</h2><p>Anda baru merasakan booking → admin → pembayaran → invoice → kalender → housekeeping → owner.</p><div class="notice">Semua itu termasuk Standard, Rp249.000/bulan. Pro menambah ruang bertumbuh, selisih Rp200.000/bulan.</div>${btn('Coba Pro '+icon('arrow'),'go-pro')}`);return}if(state.step===5){goPro();return}if(state.step===6){state.step=7;switchPlan('Enterprise','portfolio');return}if(state.step===7){state.step=8;navigate('pricing','Owner');return}navigate('contact','Owner')}
function goPro(){state.step=6;switchPlan('Pro','crm')}
function render(){const pages={overview:dashboard,today,bookings,guest,unit:unitDetail,checkout,confirmation,booking:detail,invoice,calendar,housekeeping,finance,guests,crm,automation,rules,portfolio,central:()=>guests(true),team,pricing,calculator,contact};$('#app').innerHTML=landing?landingPage():appShell((pages[state.page]||dashboard)());persist()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action,page=el.dataset.page;switch(a){case'home':landing=true;render();window.scrollTo(0,0);break;case'guided':$('#modal').close();start(true);break;case'explore':start(false);break;case'guest':state.guided=false;navigate('guest','Guest');break;case'admin':state.guided=false;navigate('today','Admin');break;case'owner':state.guided=false;navigate('overview','Owner');break;case'role':state.role=el.dataset.role;track('role_switched',{role:state.role});navigate(state.role==='Guest'?'guest':state.role==='Admin'?'today':'overview');break;case'nav':if(!available(page)){locked(page);break}if(page==='guest')state.role='Guest';if(page==='overview')state.role='Owner';navigate(page);break;case'pricing':$('#modal').close();navigate('pricing',state.role==='Guest'?'Owner':undefined);break;case'calculator':navigate('calculator','Owner');break;case'contact':navigate('contact','Owner');break;case'choose-plan':state.interest=el.dataset.plan;navigate('contact','Owner');break;case'yearly':state.yearly=true;render();break;case'monthly':state.yearly=false;render();break;case'unit':state.unit=Number(el.dataset.unit);navigate('unit','Guest');break;case'checkout':if(conflict(state.unit)){toast('Unit sudah dipesan di tanggal ini. Pilih tanggal atau unit lain.');break}if(state.guests>units[state.unit].capacity){toast('Jumlah tamu melebihi kapasitas. Pilih unit yang lebih besar.');break}navigate('checkout','Guest');break;case'new-booking':state.guided=false;navigate('guest','Guest');break;case'to-admin':state.step=1;track('role_switched',{role:'Admin'});navigate('today','Admin');break;case'to-owner':state.step=4;track('role_switched',{role:'Owner'});navigate('overview','Owner');break;case'bookings':navigate('bookings','Admin');break;case'booking-detail':if(el.dataset.id)state.selected=el.dataset.id;navigate('booking','Admin');break;case'payment':payment();break;case'invoice':navigate('invoice');break;case'calendar':if(state.guided&&state.step<=2)state.step=3;navigate('calendar','Admin');break;case'housekeeping':navigate('housekeeping','Admin');break;case'ready':state.hk[Number(el.dataset.unit)]='Ready';if(state.guided)state.step=4;persist();render();toast('Kamar Ready · Tim dapat melihat status yang sama.');break;case'crm':case'portfolio':case'central':case'team':if(!available(a)){locked(a);break}navigate(a,'Owner');break;case'unlock':$('#modal').close();if(state.guided)state.step=el.dataset.plan==='Pro'?6:7;switchPlan(el.dataset.plan,el.dataset.page);break;case'offer':state.offer=true;track('repeat_offer_sent_demo');render();toast('Penawaran terkirim — Demo. Tidak ada pesan asli dikirim.');break;case'toggle-rule':state.rules[el.dataset.rule]=!state.rules[el.dataset.rule];persist();render();toast('Aturan simulasi diperbarui');break;case'save-pricing':{const v=Number($('#weekend').value);if(!Number.isFinite(v)||v<0||v>100){toast('Isi kenaikan antara 0–100%.');break}state.weekend=v;persist();toast('Aturan harga tersimpan — Demo');break}case'view-property':state.property=Number(el.dataset.property);navigate('overview','Owner');break;case'guest-history':{const bs=state.bookings.filter(b=>b.name===el.dataset.name);modal(`<div class="eyebrow">RIWAYAT TAMU · DEMO</div><h2>${esc(el.dataset.name)}</h2><p>${bs.length} booking dalam database simulasi.</p>${bs.map(b=>`<div class="summary-line"><span>${units[b.unit].name}<small style="display:block">${b.checkin} · ${b.id}</small></span><strong>${money(b.total)}</strong></div>`).join('')}`);break}case'reset':modal(`<div class="eyebrow">MULAI DARI AWAL</div><h2>Reset demo ini?</h2><p>Booking percobaan, pembayaran, status kamar, pricing rules, dan progres demo di perangkat ini akan kembali ke data awal.</p><div class="dialog-actions">${btn('Reset demo','confirm-reset')}${btn('Lanjutkan eksplorasi','close','outline')}</div>`);break;case'confirm-reset':state=initial();persist();$('#modal').close();landing=false;render();toast('Demo kembali ke kondisi awal.');break;case'close':$('#modal').close();break;case'next':next();break;case'unguided':state.guided=false;render();break;case'go-pro':$('#modal').close();goPro();break;case'standard-summary':next();break;case'print':window.print();break;case'privacy':modal(`<div class="eyebrow">PRIVASI DEMO</div><h2>Ruang aman untuk mencoba.</h2><p>Data booking, progres, dan event interaksi hanya disimpan di localStorage browser ini. Tidak ada analytics eksternal, pengiriman email otomatis, pesan WhatsApp otomatis, atau pembayaran asli.</p><p>Gunakan identitas fiktif. Reset demo menghapus seluruh percobaan di perangkat ini. CTA konsultasi membuka WhatsApp; pesan dikirim hanya setelah Anda mengirimnya sendiri.</p>`);break;case'email':{const text=`Halo tim Nginepin, saya tertarik paket ${state.interest}. Saya ingin konsultasi untuk bisnis penginapan saya.`;track('CTA_clicked',{channel:'email',plan:state.interest});window.location.href='mailto:admin3@desainindongmas.my.id?subject='+encodeURIComponent('Konsultasi Nginepin — '+state.interest)+'&body='+encodeURIComponent(text);break}}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='plan-select'){switchPlan(t.value);if(!available(state.page))navigate(state.role==='Admin'?'today':'overview');}if(t.id==='property-select'){const p=Number(t.value);if(p!==0&&state.plan!=='Enterprise'){render();locked('portfolio');return}state.property=p;if(p===-1){state.interest='Enterprise';navigate('portfolio','Owner')}else{persist();render()}}if(t.id==='bbq'||t.name==='payment'){state.bbq=$('#bbq').checked;state.full=$('input[name="payment"]:checked').value==='full';$('#checkout-summary').innerHTML=checkoutSummary();persist()}if(t.dataset.hk!==undefined){state.hk[Number(t.dataset.hk)]=t.value;if(state.guided&&t.value==='Ready')state.step=4;persist();render();toast('Status kamar diperbarui — Demo')}if(t.id==='booking-status'){const b=picked();b.status=t.value;persist();render();toast('Status reservasi diperbarui — Demo')}});
document.addEventListener('input',e=>{if(e.target.id==='booking-search'){query=e.target.value;$('#booking-table').innerHTML=bookingTable(filteredBookings())}if(e.target.id==='weekend'){const v=Number(e.target.value);$('#weekend-preview').textContent=money(1200000*(1+v/100))}});
document.addEventListener('submit',e=>{const f=e.target;e.preventDefault();if(!f.checkValidity()){f.reportValidity();return}if(f.id==='availability-form'){const ci=$('#checkin').value,co=$('#checkout').value,n=Math.round((new Date(co)-new Date(ci))/86400000);if(n<1||n>30){toast('Pilih lama menginap 1–30 malam.');return}state.checkin=ci;state.checkout=co;state.guests=Number($('#guests').value);persist();render();toast('Ketersediaan diperbarui untuk tanggal pilihan Anda.')}if(f.id==='checkout-form')createBooking(f);if(f.id==='payment-form'){const b=picked(),amount=Number($('#pay-amount').value);if(!Number.isFinite(amount)||amount<=0||amount>b.total-b.paid){toast('Nominal harus sesuai sisa pembayaran.');return}b.payments.push({amount,method:$('#pay-method').value+' · Demo',date:'Sekarang'});b.paid+=amount;if(state.guided)state.step=2;track('payment_recorded',{booking_id:b.id,amount});$('#modal').close();render();toast(b.paid>=b.total?'Pembayaran lunas · Outstanding Rp0 · Invoice otomatis LUNAS':'Pembayaran tercatat · Outstanding otomatis diperbarui')}if(f.id==='calc-form'){const r=Number($('#ota-revenue').value),fee=Number($('#ota-fee').value),s=Number($('#ota-shift').value);$('#calc-result').innerHTML=calcResult(r,fee,s);track('savings_calculated',{revenue:r,fee,shift:s})}if(f.id==='contact-form'){const business=$('#business-name').value.trim(),plan=$('#contact-plan').value,count=$('#property-count').value,msg=`Halo tim Nginepin, saya ingin konsultasi.\n\nNama bisnis: ${business||'Belum diisi'}\nJumlah properti: ${count}\nPaket diminati: ${plan}\nPeriode: ${state.yearly?'Tahunan':'Bulanan'}\n\nSaya sudah mencoba demo Nginepin. Mohon dibantu memilih paket yang sesuai.`;track('CTA_clicked',{channel:'whatsapp',plan});window.open('https://wa.me/6285952839393?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer')}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
render();
